class DB {
  late SharedPreferences prefs;
  List<Map<String, dynamic>> items = [];
  List<Map<String, dynamic>> customers = [];
  List<Map<String, dynamic>> rentals = [];
  Future<void> load() async { prefs = await SharedPreferences.getInstance(); items = read('items'); customers = read('customers'); rentals = read('rentals'); }
  List<Map<String, dynamic>> read(String key) { final s = prefs.getString(key); if (s == null) return []; return (jsonDecode(s) as List).map((e) => Map<String, dynamic>.from(e)).toList(); }
  Future<void> save() async { await prefs.setString('items', jsonEncode(items)); await prefs.setString('customers', jsonEncode(customers)); await prefs.setString('rentals', jsonEncode(rentals)); }
}
int asInt(dynamic v) => v is int ? v : int.tryParse('$v') ?? 0;
double asDouble(dynamic v) => v is num ? v.toDouble() : double.tryParse('$v') ?? 0;
String money(dynamic v) { final d = asDouble(v); return d == d.roundToDouble() ? d.toInt().toString() : d.toStringAsFixed(2); }
String today() { final d = DateTime.now(); return '${d.day.toString().padLeft(2, '0')}/${d.month.toString().padLeft(2, '0')}/${d.year}'; }

class Shell extends StatefulWidget { const Shell({super.key}); @override State<Shell> createState() => _ShellState(); }
class _ShellState extends State<Shell> {
  final db = DB(); int tab = 0; bool loading = true; DateTime? lastBack;
  @override void initState() { super.initState(); load(); }
  Future<void> load() async { await db.load(); if (mounted) setState(() => loading = false); }
  void refresh() => setState(() {});
  Future<bool> handleBack() async { if (tab != 0) { setState(() => tab = 0); return false; } final now = DateTime.now(); if (lastBack != null && now.difference(lastBack!) < const Duration(seconds: 2)) return true; lastBack = now; if (mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Press back again to exit'), duration: Duration(seconds: 2))); return false; }
  @override Widget build(BuildContext context) {
    if (loading) return const Scaffold(body: Center(child: CircularProgressIndicator(color: primary)));
    final pages = [Home(db: db, refresh: refresh, selectTab: (i) => setState(() => tab = i)), ItemsPage(db: db, refresh: refresh), CustomersPage(db: db, refresh: refresh), ReportsPage(db: db)];
    return PopScope<bool>(canPop: false, onPopInvokedWithResult: (didPop, result) async { if (!didPop) { final allow = await handleBack(); if (allow && context.mounted) Navigator.of(context).maybePop(); } }, child: Scaffold(body: IndexedStack(index: tab, children: pages), bottomNavigationBar: NavigationBar(selectedIndex: tab, onDestinationSelected: (i) => setState(() => tab = i), indicatorColor: mint, destinations: const [NavigationDestination(icon: Icon(Icons.home_outlined), selectedIcon: Icon(Icons.home_rounded), label: 'Home'), NavigationDestination(icon: Icon(Icons.inventory_2_outlined), selectedIcon: Icon(Icons.inventory_2_rounded), label: 'Items'), NavigationDestination(icon: Icon(Icons.people_outline), selectedIcon: Icon(Icons.people_rounded), label: 'Customers'), NavigationDestination(icon: Icon(Icons.analytics_outlined), selectedIcon: Icon(Icons.analytics_rounded), label: 'Reports')]));
  }
}

