Future<void> itemForm(BuildContext context, DB db, VoidCallback refresh) async { final name = TextEditingController(), category = TextEditingController(), qty = TextEditingController(), rate = TextEditingController(); String type = 'Per Day'; await Navigator.push(context, MaterialPageRoute(builder: (_) => StatefulBuilder(builder: (c, set) => FormPage(title: 'Add Item', children: [field(name, 'Item Name'), field(category, 'Category'), field(qty, 'Total Quantity', number: true), field(rate, 'Rent Price', number: true), DropdownButtonFormField<String>(initialValue: type, decoration: const InputDecoration(labelText: 'Rent Type'), items: const ['Per Day', 'Per Hour', 'Per Event'].map((x) => DropdownMenuItem(value: x, child: Text(x))).toList(), onChanged: (v) => set(() => type = v ?? 'Per Day')), const SizedBox(height: 20), FilledButton(onPressed: () async { if (name.text.trim().isEmpty) return; final n = int.tryParse(qty.text) ?? 0; db.items.add({'id': DateTime.now().microsecondsSinceEpoch.toString(), 'name': name.text.trim(), 'category': category.text.trim(), 'qty': n, 'available': n, 'rate': double.tryParse(rate.text) ?? 0, 'type': type}); await db.save(); refresh(); if (c.mounted) Navigator.pop(c); }, child: const Text('Save Item'))])))); }

Future<void> customerForm(BuildContext context, DB db, VoidCallback refresh) async { final name = TextEditingController(), mobile = TextEditingController(), address = TextEditingController(); await Navigator.push(context, MaterialPageRoute(builder: (_) => FormPage(title: 'Add Customer', children: [field(name, 'Customer Name'), field(mobile, 'Mobile Number', number: true), field(address, 'Address', lines: 3), const SizedBox(height: 20), FilledButton(onPressed: () async { if (name.text.trim().isEmpty) return; db.customers.add({'name': name.text.trim(), 'mobile': mobile.text.trim(), 'address': address.text.trim()}); await db.save(); refresh(); if (context.mounted) Navigator.pop(context); }, child: const Text('Save Customer'))]))); }

Future<void> rentalForm(BuildContext context, DB db, VoidCallback refresh) async { if (db.items.isEmpty || db.customers.isEmpty) { ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Add at least one item and one customer first'))); return; } String customer = db.customers.first['name'] as String; String item = db.items.first['name'] as String; final q = TextEditingController(text: '1'), d = TextEditingController(text: '1'), r = TextEditingController(text: money(db.items.first['rate'])); await Navigator.push(context, MaterialPageRoute(builder: (_) => StatefulBuilder(builder: (c, set) => FormPage(title: 'New Rental', children: [DropdownButtonFormField<String>(initialValue: customer, decoration: const InputDecoration(labelText: 'Customer'), items: db.customers.map((x) => DropdownMenuItem(value: x['name'] as String, child: Text(x['name'] as String))).toList(), onChanged: (v) => set(() => customer = v ?? customer)), const SizedBox(height: 12), DropdownButtonFormField<String>(initialValue: item, decoration: const InputDecoration(labelText: 'Item'), items: db.items.map((x) => DropdownMenuItem(value: x['name'] as String, child: Text(x['name'] as String))).toList(), onChanged: (v) { final n = v ?? item; set(() { item = n; r.text = money(db.items.firstWhere((x) => x['name'] == n)['rate']); }); }), field(q, 'Quantity', number: true), field(d, 'Days / Hours', number: true), field(r, 'Rate', number: true), const SizedBox(height: 20), FilledButton(onPressed: () async { final qty = int.tryParse(q.text) ?? 0; final days = int.tryParse(d.text) ?? 0; final rate = double.tryParse(r.text) ?? 0; final it = db.items.firstWhere((x) => x['name'] == item); if (qty <= 0 || qty > asInt(it['available'])) { ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content: Text('Quantity is not available'))); return; } it['available'] = asInt(it['available']) - qty; db.rentals.add({'date': today(), 'customer': customer, 'item': item, 'qty': qty, 'received': 0, 'days': days, 'rate': rate, 'amount': qty * days * rate}); await db.save(); refresh(); if (c.mounted) Navigator.pop(c); }, child: const Text('Create Rental / Invoice'))])))); }

Future<void> receiveForm(BuildContext context, DB db, VoidCallback refresh) async { final active = db.rentals.where((r) => asInt(r['qty']) > asInt(r['received'])).toList(); if (active.isEmpty) { ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('No issued items to receive'))); return; } final r = active.first; final qty = TextEditingController(text: '${asInt(r['qty']) - asInt(r['received'])}'); await Navigator.push(context, MaterialPageRoute(builder: (_) => FormPage(title: 'Receive Item', children: [Card(child: ListTile(title: Text('${r['item']}', style: const TextStyle(fontWeight: FontWeight.w900)), subtitle: Text('${r['customer']} • Issued ${r['qty']} • Received ${r['received']}'))), const SizedBox(height: 14), field(qty, 'Received Quantity', number: true), const SizedBox(height: 20), FilledButton(onPressed: () async { final n = int.tryParse(qty.text) ?? 0; final remaining = asInt(r['qty']) - asInt(r['received']); if (n <= 0 || n > remaining) return; r['received'] = asInt(r['received']) + n; final it = db.items.firstWhere((x) => x['name'] == r['item']); it['available'] = asInt(it['available']) + n; await db.save(); refresh(); if (context.mounted) Navigator.pop(context); }, child: const Text('Save Received'))]))); }

void customerReport(BuildContext context, DB db, String name) { final rows = db.rentals.where((r) => r['customer'] == name).toList(); Navigator.push(context, MaterialPageRoute(builder: (_) => Scaffold(appBar: AppBar(title: Text(name, style: const TextStyle(fontWeight: FontWeight.w900))), body: ListView(padding: const EdgeInsets.all(20), children: [Card(child: Padding(padding: const EdgeInsets.all(16), child: Row(children: [Expanded(child: summary('Issued', rows.fold<int>(0, (s, r) => s + asInt(r['qty'])))), Expanded(child: summary('Received', rows.fold<int>(0, (s, r) => s + asInt(r['received'])))), Expanded(child: summary('Item Due', rows.fold<int>(0, (s, r) => s + asInt(r['qty']) - asInt(r['received']))))]))), const SizedBox(height: 14), ...rows.map((r) => Card(child: ListTile(title: Text('${r['item']}', style: const TextStyle(fontWeight: FontWeight.w900)), subtitle: Text('${r['date']} • ${r['days']} day(s) • ₹${money(r['rate'])}'), trailing: Text('₹${money(r['amount'])}\nDue ${asInt(r['qty']) - asInt(r['received'])}', textAlign: TextAlign.right)))).toList()]))); }
Widget summary(String a, int b) => Column(children: [Text('$b', style: const TextStyle(fontSize: 22, fontWeight: FontWeight.w900, color: primary)), Text(a, style: const TextStyle(fontSize: 12, color: muted))]);

void invoiceList(BuildContext context, DB db) { Navigator.push(context, MaterialPageRoute(builder: (_) => Scaffold(appBar: AppBar(title: const Text('Invoices', style: TextStyle(fontWeight: FontWeight.w900))), body: ListView(padding: const EdgeInsets.all(20), children: db.rentals.reversed.map((r) => Card(child: ListTile(leading: const CircleAvatar(backgroundColor: mint, child: Icon(Icons.receipt_long_rounded, color: primary)), title: Text('Invoice • ${r['customer']}', style: const TextStyle(fontWeight: FontWeight.w900)), subtitle: Text('${r['date']} • ${r['item']} • ${r['days']} day(s)'), trailing: Text('₹${money(r['amount'])}', style: const TextStyle(fontWeight: FontWeight.w900)))).toList()))); }
void showAbout(BuildContext context) => showAboutDialog(context: context, applicationName: 'RentFlow', applicationVersion: '1.0.0', applicationIcon: const Brand(size: 52), children: const [Text('By PaliaAPK HUB'), SizedBox(height: 6), Text('Developer by ShanPalia')]);
